pub fn eval_source(
    engine_state: &mut EngineState,
    stack: &mut Stack,
    source: &[u8],
    fname: &str,
    input: PipelineData,
    allow_return: bool,
) -> i32 {
    let start_time = std::time::Instant::now();

    let exit_code = match evaluate_source(engine_state, stack, source, fname, input, allow_return) {
        Ok(code) => code.unwrap_or(0),
        Err(err) => {
            report_error_new(engine_state, &err);
            1
        }
    };

    stack.add_env_var(
        "LAST_EXIT_CODE".to_string(),
        Value::int(exit_code.into(), Span::unknown()),
    );

    // reset vt processing, aka ansi because illbehaved externals can break it
    #[cfg(windows)]
    {
        let _ = enable_vt_processing();
    }

    perf(
        &format!("eval_source {}", &fname),
        start_time,
        file!(),
        line!(),
        column!(),
        engine_state.get_config().use_ansi_coloring,
    );

    exit_code
}

fn evaluate_source(
    engine_state: &mut EngineState,
    stack: &mut Stack,
    source: &[u8],
    fname: &str,
    input: PipelineData,
    allow_return: bool,
) -> Result<Option<i32>, ShellError> {
    let (block, delta) = {
        let mut working_set = StateWorkingSet::new(engine_state);
        let output = parse(
            &mut working_set,
            Some(fname), // format!("entry #{}", entry_num)
            source,
            false,
        );
        if let Some(warning) = working_set.parse_warnings.first() {
            report_error(&working_set, warning);
        }

        if let Some(err) = working_set.parse_errors.first() {
            report_error(&working_set, err);
            return Ok(Some(1));
        }

        (output, working_set.render())
    };

    engine_state.merge_delta(delta)?;

    let pipeline = if allow_return {
        eval_block_with_early_return::<WithoutDebug>(engine_state, stack, &block, input)
    } else {
        eval_block::<WithoutDebug>(engine_state, stack, &block, input)
    }?;

    let status = if let PipelineData::ByteStream(stream, ..) = pipeline {
        stream.print(false)?
    } else {
        if let Some(hook) = engine_state.get_config().hooks.display_output.clone() {
            let pipeline = eval_hook(
                engine_state,
                stack,
                Some(pipeline),
                vec![],
                &hook,
                "display_output",
            )?;
            pipeline.print(engine_state, stack, false, false)
        } else {
            pipeline.print(engine_state, stack, true, false)
        }?
    };

    Ok(status.map(|status| status.code()))
}

